/**
 * Where an upload's bytes live.
 *
 * The key is generated by the server and never supplied by the client. A
 * client-chosen key is a request to write over someone else's object, and a
 * presigned URL would authorise exactly that.
 *
 * The owner's identifier is part of the path so that an object can be traced
 * to an account without a database lookup — which matters for erasure, where
 * the question is "what belongs to this person" and the answer must not depend
 * on a read model that may already have been cleared.
 */

/**
 * The key for an upload's original bytes.
 *
 * @param ownerUserId - Who the upload belongs to.
 * @param uploadId - The upload's identifier, which makes the key unique.
 * @returns The object key. Stable: it is recorded at registration and read
 *   back afterwards rather than recomputed, so changing this function cannot
 *   orphan existing objects.
 */
export function originalKey(ownerUserId: string, uploadId: string): string {
  return `uploads/${ownerUserId}/${uploadId}/original`;
}
